import { workflowTemplate } from "./workflow.template.js";
import { fastfileTemplate } from "./fastfile.template.js";
import { gemfileTemplate } from "./gemfile.template.js";
export function renderGitHubWorkflow(options) {
    return workflowTemplate(options);
}
export function renderFastfile(options) {
    return fastfileTemplate(options);
}
export function renderGemfile() {
    return gemfileTemplate();
}
export function renderReadme(options) {
    return `# Android CI

Generated by android-ci init.

## Build choices

- **debug-apk**: creates an installable debug APK and uploads it as a GitHub artifact.
- **production**: signs an Android App Bundle, uploads it as an artifact, and${options.enablePlayDeploy ? " deploys it to Google Play" : " skips the Play Store upload"}.
- Pushes to main and pull requests run the debug APK build. Production must be selected manually.

## Expo prebuild layout

The workflow generates ${options.androidProjectPath}/ with Expo prebuild on the GitHub runner. Keep that generated native directory out of Git. Fastlane is kept in the repository root so it survives prebuild:

- Gemfile
- fastlane/Fastfile
- scripts/patch-android-release-signing.mjs

## GitHub Actions secrets

- ANDROID_KEYSTORE_BASE64
- ANDROID_KEYSTORE_PASSWORD
- ANDROID_KEY_ALIAS
- ANDROID_KEY_PASSWORD
${options.enablePlayDeploy ? "- PLAY_STORE_JSON_BASE64\n" : ""}- GOOGLE_SERVICES_JSON_BASE64 when app.json configures android.googleServicesFile.

Set the secrets in the repository's **Settings → Secrets and variables → Actions**.

${options.enablePlayDeploy ? `The workflow defaults to the production Play track. Set the repository variable PLAY_TRACK to change it. The service account must have access to the Play Console app for ${options.androidApplicationId}.

` : ""}## Run it

Open **Actions → Android CI → Run workflow** and choose **debug-apk** or **production**.
`;
}
